{
  "schema_version": 1,
  "template_id": "finance-analyst",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm role and purpose",
      "instructions": "Read this Crew's saved identity and purpose. Confirm it is authorized to analyze finance records, even if its role also covers another installed template. Do not overwrite its identity merely to fit this pack."
    },
    {
      "id": "skill",
      "title": "Verify the finance skill",
      "instructions": "Confirm skills/finance-analyst/SKILL.md exists and finance-analyst is selected for this Crew. Complete only after both checks pass."
    },
    {
      "id": "data_source",
      "title": "Choose a data source",
      "instructions": "Ask the owner for an uploaded statement or an authorized finance connection. Verify one actual source row and its ID, period, entity, account, currency, opening/closing cutoff and coverage. An uploaded file is sufficient; do not require an MCP connection."
    },
    {
      "id": "period_currency",
      "title": "Set period and currency",
      "instructions": "Agree on the reporting period and currency. Save stable preferences in MEMORY.md, and complete only after the owner confirms them."
    },
    {
      "id": "metrics",
      "title": "Define the numbers",
      "instructions": "Agree on the measures used for invoiced, recognized and collected amounts, refunds, fees, bank deposits and expenses. Confirm accounting basis, sign, currency/FX source, period cutoff, matching IDs and reconciliation tolerance. Reproduce one source-linked calculation and save stable definitions in MEMORY.md."
    },
    {
      "id": "first_brief",
      "title": "Test the first brief",
      "instructions": "Produce a finance brief from authorized data with source rows, calculations, opening/closing cutoff and explicit unreconciled items. Demonstrate one matching and one missing/ambiguous record or state that none was found. Ask the owner to review it; complete only after a brief was produced and the owner confirms it is useful."
    },
    {
      "id": "delivery",
      "title": "Decide where briefs go",
      "optional": true,
      "instructions": "Ask whether briefs stay in Crew chat or go to an approved Slack or email destination. Choosing chat-only or not needed is a valid completed decision. Do not send anything without explicit authorization."
    },
    {
      "id": "recurrence",
      "title": "Decide on recurring work",
      "optional": true,
      "instructions": "Ask whether the owner wants a schedule or new-statement trigger. Choosing not needed is valid. If requested, agree on timezone or event source, test the result, and enable only with authorization."
    },
    {
      "id": "sharing",
      "title": "Decide on reusable access",
      "optional": true,
      "instructions": "Ask whether other Crews need an analyze_finances function or whether a separate goal-based Automation is useful. Choosing neither is valid. Review permissions and the contract before exposing either."
    }
  ],
  "completed_steps": []
}

files.templates/invoice-chasing/TEMPLATE_SETUP:
{
  "schema_version": 1,
  "template_id": "invoice-chasing",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm Billing Crew identity and owner",
      "instructions": "Confirm whether this pack extends an existing Billing Operations Coordinator Crew or is its primary capability. Preserve the existing Crew identity and name its accountable owner."
    },
    {
      "id": "skill",
      "title": "Verify pack skill",
      "instructions": "Confirm skills/invoice-chasing/SKILL.md exists and invoice-chasing is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Bind exact case and account scope",
      "instructions": "Record business, provider account/mode, customer, case type, currency, time zone and first job. Minimum input: Authorized invoice and payment records, business and account ID, reporting cutoff, invoice terms, contact policy, suppression rules, and collections owner."
    },
    {
      "id": "access",
      "title": "Probe current records",
      "instructions": "Read one real authorized current case plus linked status/action history; record IDs, observed time and missing coverage. Billing provider such as Stripe or Paddle, CRM and support inbox via scoped MCPs or exports; a read-only export can support the first queue."
    },
    {
      "id": "policy",
      "title": "Confirm policy and action boundary",
      "instructions": "Record owner policy, deadline or retry rule, approval authority, recipient/contact boundary and duplicate key. Do not send a reminder, change terms, mark an invoice paid or uncollectible, or initiate a charge through installation. A send needs exact-recipient approval, current state recheck and provider receipt."
    },
    {
      "id": "first_result",
      "title": "Produce a sourced first result",
      "instructions": "Produce A ranked overdue-invoice queue with invoice/customer IDs, open amount, due and last-payment dates, prior or scheduled contact, owner, and unsent next message. A follow-up row needs current invoice/payment source IDs, observed time, amount remaining in minor units and currency, prior-contact source, policy rule, and reason it is due now. Fictional examples do not complete setup."
    },
    {
      "id": "review",
      "title": "Review with case owner",
      "instructions": "Show provider state, calculations, prior actions, unknowns and proposed next step. Record an owner correction or explicit approval decision."
    },
    {
      "id": "delivery",
      "title": "Choose read-only or action route",
      "optional": true,
      "instructions": "Choose chat-only review or a separately authorized exact-object action route. Chat-only completes this choice; a draft is never a sent message, refund, retry or dispute submission."
    },
    {
      "id": "recurrence",
      "title": "Choose manual or recurring work",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed authenticated event/schedule with stable IDs, deduplication, retries, cost and notifications. Manual-only completes this choice. Re-read current payment and prior-contact state, deduplicate by invoice and contact action ID, respect quiet periods and provider dunning, and close or defer resolved cases."
    }
  ],
  "completed_steps": []
}

